INSERT INTO public.flashcards (deck_category, front_content, back_content) VALUES
('Fundamentos de Enfermagem', 'Quais são os ângulos corretos para as injeções Intramuscular (IM), Subcutânea (SC), Intravenosa (EV) e Intradérmica (ID)?', 'IM: 90 graus / SC: 45 a 90 graus / EV: 25 a 30 graus / ID: 10 a 15 graus.'),
('Fundamentos de Enfermagem', 'O que é a Respiração de Cheyne-Stokes?', 'Padrão respiratório caracterizado por períodos alternados de apneia e respirações profundas e rápidas (crescente e decrescente). Comum em lesões neurológicas e insuficiência cardíaca grave.'),
('Fundamentos de Enfermagem', 'Qual é a diferença visual e de finalidade entre a Sonda Nasogástrica (SNG) e a Sonda Nasoentérica (SNE)?', 'SNG: Calibre maior, curta, usada para drenagem/lavagem gástrica. SNE: Calibre menor, longa, possui fio-guia e ogiva (peso) na ponta, usada exclusivamente para alimentação no duodeno/jejunum.'),
('Fundamentos de Enfermagem', 'Quais são as 4 etapas do exame físico (propedêutica) tradicional, em ordem?', '1. Inspeção / 2. Palpação / 3. Percussão / 4. Ausculta. (Obs: No abdome a ordem muda para Inspeção, Ausculta, Percussão e Palpação).'),
('Fundamentos de Enfermagem', 'Como se caracteriza uma Lesão por Pressão (LPP) de Estágio 2?', 'Perda de espessura parcial da pele com exposição da derme. O leito da ferida é viável, de coloração rosa ou vermelha, úmido, podendo também apresentar-se como uma bolha intacta ou rompida.'),
('Fundamentos de Enfermagem', 'O que é a Posição de Sims e para que ela é indicada?', 'Paciente em decúbito lateral esquerdo, com a perna direita flexionada sobre a esquerda. É a posição ideal para a realização de enemas (lavagem intestinal) e exames retais.'),
('Fundamentos de Enfermagem', 'Quais os valores normais de Frequência Cardíaca (Pulso) e Frequência Respiratória em um adulto em repouso?', 'FC: 60 a 100 batimentos por minuto (bpm). FR: 12 a 20 incursões respiratórias por minuto (irpm).'),
('Fundamentos de Enfermagem', 'Qual a diferença anatômica na aplicação da regra de oxigenoterapia via Cateter Nasal tipo Óculos?', 'Fornece baixo fluxo de oxigênio (geralmente de 1 a 5 L/min), atingindo no máximo uma FiO2 de cerca de 40 a 44% (não serve para pacientes precisando de alta concentração exata de O2).'),
('Fundamentos de Enfermagem', 'Como deve ser realizada a higiene íntima feminina durante o banho no leito para evitar infecções?', 'A limpeza deve ser feita sempre no sentido ântero-posterior (da região pubiana em direção à região anal) para evitar que bactérias do trato gastrointestinal alcancem a uretra e vagina.'),
('Fundamentos de Enfermagem', 'O que caracteriza a febre intermitente?', 'Picos de hipertermia alternados com períodos de temperatura normal (apirexia). A temperatura volta ao normal pelo menos uma vez a cada 24 horas (ex: Malária, Sepse).'),
('Fundamentos de Enfermagem', 'Para qual procedimento é indicada a posição Genupeitoral?', 'Exames proctológicos (reto e ânus) ou procedimentos vaginais específicos. O paciente ajoelha-se sobre a cama com o peito e a face apoiados no colchão.'),
('Fundamentos de Enfermagem', 'Qual o padrão-ouro atual para confirmar o posicionamento de uma Sonda Nasoentérica antes de iniciar a dieta?', 'Radiografia de abdome (Raio-X). Testes de ausculta ou aspiração não são 100% seguros.'),
('Fundamentos de Enfermagem', 'Na classificação de feridas, o que é o tecido de granulação e qual a sua cor?', 'É o tecido de cicatrização saudável, altamente vascularizado. Possui coloração vermelha brilhante ou vermelho-framboesa e aspecto granular.'),
('Fundamentos de Enfermagem', 'O que é pulso filiforme?', 'É um pulso fraco, fino e difícil de palpar. Geralmente associado a quadros de hipotensão severa, choque ou hemorragia.'),
('Fundamentos de Enfermagem', 'Qual o local prioritário e mais seguro recomendado para aplicação de injeção Intramuscular (IM) em adultos?', 'Músculo Ventroglúteo (Região de Hochstetter), por ser livre de vasos e nervos importantes e ter tecido muscular espesso.'),
('Fundamentos de Enfermagem', 'O que é a Respiração de Kussmaul e quando ela ocorre?', 'Padrão respiratório profundo, rápido e trabalhoso (inspirar e expirar profundamente sem pausas). Clássico na Cetoacidose Diabética (tentativa de expulsar CO2 do corpo).'),
('Fundamentos de Enfermagem', 'Em relação à cor da pele, defina: Cianose, Icterícia e Eritema.', 'Cianose: coloração azulada/arroxeada (falta de oxigênio). Icterícia: coloração amarelada (excesso de bilirrubina). Eritema: vermelhidão na pele (inflamação/vasodilatação).'),
('Fundamentos de Enfermagem', 'O que caracteriza uma Lesão por Pressão Não Estagiável (Inclassificável)?', 'É aquela em que a perda total da espessura da pele e dos tecidos está completamente obscurecida por esfacelo (tecido amarelo/branco/cinza) ou escara (tecido necrótico escuro) no leito da ferida.'),
('Fundamentos de Enfermagem', 'Na aferição da Pressão Arterial, como as Fases 1 e 5 dos Sons de Korotkoff se relacionam com a PA?', 'A Fase 1 (primeiro som ouvido) determina a Pressão Sistólica. A Fase 5 (desaparecimento completo dos sons) determina a Pressão Diastólica em adultos.'),
('Fundamentos de Enfermagem', 'Qual a principal finalidade da Sonda de Foley e da Sonda de Nelaton?', 'Foley: Cateterismo vesical de DEMORA (tem balão de retenção para fixação contínua). Nelaton: Cateterismo vesical de ALÍVIO (sem balão, usada apenas para esvaziar a bexiga pontualmente e retirada logo a seguir).');